# Generated by build.py from recipe.yml for recipe imap-log-in-to-mail-with-a-token. Do not edit.
Set-Location $PSScriptRoot
[IO.File]::WriteAllText((Join-Path $PWD 'lunch.eml'), "From: bob@example.com`nTo: ann@example.com`nSubject: Lunch`n`nNoon at the usual place.`n")
cmd /c 'openssl req -x509 -newkey rsa:2048 -nodes -keyout server.key -out server.pem -days 30 -subj "/CN=127.0.0.1" -addext "subjectAltName=IP:127.0.0.1"'
$server0 = Start-Process surl -ArgumentList '--cert', 'server.pem', '--key', 'server.key', '--auth', 'oauthbearer,xoauth2', '--user', ':tok-abc123', '--mail-domain', 'example.com', '--mailbox', '"ann@example.com:annpass;protocols=http"', '--mailbox', '"bob@example.com:bobpass;protocols=http"', 'smtps://127.0.0.1:8080/', 'imaps://127.0.0.1:8081/', 'smtp://127.0.0.1:8082/', 'imap://127.0.0.1:8083/' -PassThru -NoNewWindow
Start-Sleep 1
try { curl.exe -sS --cacert server.pem --crlf -u bob@example.com --oauth2-bearer tok-abc123 --mail-from bob@example.com --mail-rcpt ann@example.com -T lunch.eml -w "%{response_code}\n" smtps://127.0.0.1:8080/example.com --next -sS --cacert server.pem -u ann@example.com --oauth2-bearer tok-abc123 "imaps://127.0.0.1:8081/INBOX;UID=1;SECTION=TEXT" } finally { Stop-Process $server0 }
